let personeller = JSON.parse(localStorage.getItem('personeller')) || [];let sablon = JSON.parse(localStorage.getItem('sablon')) || {};let seciliPersonelIds = new Set();let aktifPersonelId = null;let aktifAnaKategori = null;let aktifAltKategori = null;function özelBildirimGoster(mesaj) {  let modal = document.createElement('div');  modal.style.cssText = `    position: fixed; top: 0; left: 0; width: 100%; height: 100%;    background: rgba(0,0,0,0.5); display: flex; align-items: center;    justify-content: center; z-index: 9999;  `;  modal.innerHTML = `    <div style="background: white; padding: 20px; border-radius: 12px; max-width: 80%; text-align: center; box-shadow: 0 4px 15px rgba(0,0,0,0.2);">      <p style="margin-top:0; font-size: 15px; color: #333; line-height: 1.4; white-space: pre-wrap;">${mesaj}</p>      <button onclick="this.parentElement.parentElement.remove()" style="background: #1e88e5; color: white; border: none; padding: 8px 20px; border-radius: 6px; font-weight: bold; cursor: pointer;">Tamam</button>    </div>  `;  document.body.appendChild(modal);}document.addEventListener("DOMContentLoaded", () => {  try {    const savedData = localStorage.getItem('personeller');    if (savedData) personeller = JSON.parse(savedData);    const savedSablon = localStorage.getItem('sablon');    if (savedSablon) sablon = JSON.parse(savedSablon);  } catch (e) {    console.error("Local storage verisi bozuk, sıfırlanıyor:", e);    localStorage.clear();  }  bilgiNotunuGuncelleVeGoster();      let aktifSayfa = sessionStorage.getItem('aktifSayfa');  if (aktifSayfa === 'ayarlar') {    let vMain = document.getElementById('viewMain');    if (vMain) vMain.style.display = 'none';        let vAyarlar = document.getElementById('viewAyarlar');    if (vAyarlar) vAyarlar.style.display = 'block';        let cHeader = document.getElementById('cardHeader');    if (cHeader) cHeader.style.display = 'none';    sablonListesiniCiz();    let kaydedilenNot = localStorage.getItem('anaSayfaBilgiNotu') || '';    let input = document.getElementById('bilgiNotuInput');    if (input) input.value = kaydedilenNot;    return;  } else {    // Ana sayfadaysa cardHeader orijinal görünümüne döner    let cHeader = document.getElementById('cardHeader');    if (cHeader) cHeader.style.display = '';  }  if (!history.state) {    history.replaceState({ ekran: 'main' }, "");  }  let savedState = sessionStorage.getItem('appState');  if (savedState) {    try {      let stateData = JSON.parse(savedState);      if (stateData.ekran === 'categories' && stateData.personelId) {        aktifPersonelId = stateData.personelId;        gorselKategoriEkraniGoster(false);        personelDetayAc(aktifPersonelId, true);      } else if (stateData.ekran === 'form' && stateData.personelId && stateData.k1 && stateData.k2) {        aktifPersonelId = stateData.personelId;        gorselKategoriEkraniGoster(false);        personelDetayAc(aktifPersonelId, true);        formEkraniAc(stateData.k1, stateData.k2, true);      } else {        gorselAnaSayfaGoster(false);      }    } catch(err) {      gorselAnaSayfaGoster(false);    }  } else {    gorselAnaSayfaGoster(false);  }});// Geri tuşu (Fiziksel donanım) history/geçmiş yönetimiwindow.addEventListener('popstate', (event) => {  let viewAyarlarEl = document.getElementById('viewAyarlar');  let viewAyarlar = viewAyarlarEl && viewAyarlarEl.style.display === 'block';  let viewFormEl = document.getElementById('viewForm');  let viewForm = viewFormEl && viewFormEl.style.display === 'block';  let viewCategoriesEl = document.getElementById('viewCategories');  let viewCategories = viewCategoriesEl && viewCategoriesEl.style.display === 'block';  if (viewAyarlar) {    sessionStorage.removeItem('aktifSayfa');    if (viewAyarlarEl) viewAyarlarEl.style.display = 'none';    let vMain = document.getElementById('viewMain');    if (vMain) vMain.style.display = 'block';    gorselAnaSayfaGoster(false);    bilgiNotunuGuncelleVeGoster();  } else if (viewForm) {    if (viewFormEl) viewFormEl.style.display = 'none';    if (viewCategoriesEl) viewCategoriesEl.style.display = 'block';    let p = personeller.find(x => String(x.id) === String(aktifPersonelId));    let ht = document.getElementById('headerTitle');    if (ht) ht.innerText = p ? p.adSoyad : "Personel Detay";    let btnBack = document.getElementById('btnBack');    if (btnBack) btnBack.style.visibility = "visible";    let btnSettings = document.getElementById('btnSettings');    if (btnSettings) btnSettings.style.visibility = "hidden";    sessionStorage.setItem('appState', JSON.stringify({ ekran: 'categories', personelId: aktifPersonelId }));  } else if (viewCategories) {    // KAPANMA SORUNUNU ÇÖZEN SATIR: Geri giderken yeni kayıt atmamak için "false" geçildi    gorselAnaSayfaGoster(false);  } else {    // Ana sayfada cihaz geri tuşuna basıldıysa varsayılan davranışıyla app kapanır  }});function kaydetLocal() {  try {    personeller.sort((a, b) => {      let idA = Number(a.id) || 0;      let idB = Number(b.id) || 0;      return idA - idB;    });    localStorage.setItem('personeller', JSON.stringify(personeller));    localStorage.setItem('sablon', JSON.stringify(sablon));  } catch (e) {    özelBildirimGoster("Kayıt başarısız! Hafıza dolu olabilir.");  }}function jsonVeritabaninaKaydet() {  kaydetLocal();  özelBildirimGoster("Tüm veriler cihaz hafızasına kaydedildi.");}function dosyaSeciciAc() {  const input = document.getElementById('jsonInput');  if(input) {    input.value = '';    setTimeout(() => { input.click(); }, 50);  }}function jsonDosyasiniIceriAl(event) {  let file = event.target.files[0];  if (!file) return;  let reader = new FileReader();  reader.onload = function(e) {    let dosyaIcerigi = e.target.result;    try {      let parsedData = JSON.parse(dosyaIcerigi);      let yuklenecekPersoneller = null;      if (Array.isArray(parsedData)) {        yuklenecekPersoneller = parsedData;      } else if (parsedData && typeof parsedData === 'object') {        if (Array.isArray(parsedData.personeller)) {          yuklenecekPersoneller = parsedData.personeller;        }        if (parsedData.sablon && typeof parsedData.sablon === 'object') {          sablon = parsedData.sablon;          localStorage.setItem('sablon', JSON.stringify(sablon));        }      }      if (!yuklenecekPersoneller || yuklenecekPersoneller.length === 0) {        throw new Error("Yedek dosyasında geçerli personel kaydı bulunamadı.");      }      let eklenenSayisi = 0;      let atlananSayisi = 0;      yuklenecekPersoneller.forEach(yedekKisi => {        let zatenVarMi = personeller.some(p => String(p.id) === String(yedekKisi.id) || (p.adSoyad && yedekKisi.adSoyad && p.adSoyad.toLowerCase() === yedekKisi.adSoyad.toLowerCase()));        if (!zatenVarMi) {          personeller.push(yedekKisi);          eklenenSayisi++;        } else {          atlananSayisi++;        }      });      kaydetLocal();      personelListesiniCiz();      ozelGunleriKontrolEtVeGoster();      event.target.value = '';      özelBildirimGoster(`Yedek başarıyla birleştirildi!\n• Eklenen Yeni Kişi: ${eklenenSayisi}\n• Zaten Listede Olan (Atlanan): ${atlananSayisi}`);    } catch (err) {      özelBildirimGoster("JSON dosyası okunurken hata oluştu: " + err.message);    }  };  reader.readAsText(file);}// Uygulama içi Geri Butonu Yöneticisifunction solButonTiklandi() {  // Geri butonuna basıldığında tarayıcı geçmişini (history) 1 adım geri alıyoruz.  // Böylece donanım tuşu ile ekran tuşu aynı davranışı (popstate tetiklenmesi) sergiler.  window.history.back();}function bilgiNotunuGuncelleVeGoster() {  const bilgiNotuAlani = document.getElementById('bilgiNotuAlani');  const kaydedilenNot = localStorage.getItem('anaSayfaBilgiNotu') || "Güncel bilgi notu bulunmuyor.";  if (bilgiNotuAlani) {    bilgiNotuAlani.innerText = kaydedilenNot;    bilgiNotuAlani.style.fontSize = "12px";     bilgiNotuAlani.style.textAlign = "center";  }}function gorselAnaSayfaGoster(pushHistory = true) {  sessionStorage.setItem('appState', JSON.stringify({ ekran: 'main' }));    let vMain = document.getElementById('viewMain');  if (vMain) vMain.style.display = 'block';    let vCat = document.getElementById('viewCategories');  if (vCat) vCat.style.display = 'none';    let vForm = document.getElementById('viewForm');  if (vForm) vForm.style.display = 'none';  // Orijinal CSS yerleşiminin (flex/grid vb.) bozulmaması için boş bırakılır  let cHeader = document.getElementById('cardHeader');  if (cHeader) cHeader.style.display = '';  let ht = document.getElementById('headerTitle');  if (ht) ht.innerText = "Personel Listesi";    let btnBack = document.getElementById('btnBack');  if (btnBack) btnBack.style.visibility = "hidden";    let btnSettings = document.getElementById('btnSettings');  if (btnSettings) btnSettings.style.visibility = "visible";    aktifPersonelId = null;  personelListesiniCiz();  ozelGunleriKontrolEtVeGoster();  bilgiNotunuGuncelleVeGoster();    if (pushHistory) {    history.pushState({ ekran: 'main' }, "");  }}function gorselKategoriEkraniGoster(pushHistory = true) {  sessionStorage.setItem('appState', JSON.stringify({ ekran: 'categories', personelId: aktifPersonelId }));  let vMain = document.getElementById('viewMain');  if (vMain) vMain.style.display = 'none';  let vCat = document.getElementById('viewCategories');  if (vCat) vCat.style.display = 'block';  let vForm = document.getElementById('viewForm');  if (vForm) vForm.style.display = 'none';  let p = personeller.find(x => String(x.id) === String(aktifPersonelId));  let ht = document.getElementById('headerTitle');  if (ht) ht.innerText = p ? p.adSoyad : "Personel Detay";  let btnBack = document.getElementById('btnBack');  if (btnBack) btnBack.style.visibility = "visible";  let btnSettings = document.getElementById('btnSettings');  if (btnSettings) btnSettings.style.visibility = "hidden";  if (pushHistory) {    history.pushState({ ekran: 'categories', personelId: aktifPersonelId }, "");  }}function personelAsilTelefonunuBul(p) {  if (!p || !p.veriler) return "";  let tel = "";  Object.keys(p.veriler).forEach(kKey => {    let kayitListesi = p.veriler[kKey];    if (Array.isArray(kayitListesi) && kayitListesi[0]) {      Object.keys(kayitListesi[0]).forEach(field => {        let fLower = field.toLowerCase();        if ((fLower.includes('tel') || fLower.includes('telefon')) && !tel) {          let yasakliKelimeler = ['eş', 'baba', 'anne', 'çocuk', 'cocuk', 'kardeş', 'kardes', 'acil', 'yakın', 'yakin', 'referans', 'veli', 'kayınvalide', 'kayinpeder'];          let baskasininTeliMi = yasakliKelimeler.some(yasak => fLower.includes(yasak));          if (!baskasininTeliMi) {            tel = kayitListesi[0][field];          }        }      });    }  });  return tel;}function ozelGunleriKontrolEtVeGoster() {  const panel = document.getElementById('birthdayPanelContainer');  if (!panel) return;  const listContent = document.getElementById('birthdayListContent');  if (!listContent) return;  listContent.innerHTML = "";  let yakinGunler = [];  let yarin = new Date();  yarin.setDate(yarin.getDate() + 1);  let yarinGun = yarin.getDate();  let yarinAy = yarin.getMonth() + 1;  personeller.forEach(p => {    if (!p.veriler) return;    let personelTel = personelAsilTelefonunuBul(p);    Object.keys(p.veriler).forEach(mainKey => {      let kayitlar = p.veriler[mainKey];      if (!Array.isArray(kayitlar)) return;      kayitlar.forEach(kayit => {        Object.keys(kayit).forEach(alanAdi => {          let deger = kayit[alanAdi];          if (!deger) return;          let parsedDate = parseTarih(deger);          if (parsedDate) {            if (parsedDate.gun === yarinGun && parsedDate.ay === yarinAy) {              yakinGunler.push({                isim: p.adSoyad,                etkinlik: alanAdi,                telefon: personelTel,                metin: `${yarinGun}.${yarinAy} (Yarın) ${p.adSoyad} (${alanAdi})`              });            }          }        });      });    });  });  if (yakinGunler.length > 0) {    panel.style.display = 'block';    yakinGunler.forEach(item => {      let li = document.createElement('li');      li.className = 'birthday-item';      let temizTel = item.telefon ? item.telefon.replace(/\D/g, '') : '';      let waButtonHtml = "";      if (temizTel) {        if (temizTel.startsWith('0') && temizTel.length === 11) temizTel = '90' + temizTel.substring(1);        else if (temizTel.length === 10) temizTel = '90' + temizTel;        let waMesaj = encodeURIComponent(`Merhaba ${item.isim}, doğum günün kutlu olsun! Nice mutlu yıllara.`);        waButtonHtml = `<a href="https://wa.me/${temizTel}?text=${waMesaj}" target="_blank" class="btn-wa-mini">💬 Kutla</a>`;      } else {        waButtonHtml = `<span style="font-size:11px; color:#999;">Tel yok</span>`;      }      li.innerHTML = `        <span style="font-weight: 500; color: #d84315;">🔔 ${item.metin}</span>        ${waButtonHtml}      `;      listContent.appendChild(li);    });  } else {    panel.style.display = 'none';  }}function parseTarih(val) {  if (!val) return null;  val = val.toString().trim();  let parts = val.split(/[.\/\\-]/);  if (parts.length >= 2) {    let g = parseInt(parts[0], 10);    let a = parseInt(parts[1], 10);    if (!isNaN(g) && !isNaN(a) && g >= 1 && g <= 31 && a >= 1 && a <= 12) {      return { gun: g, ay: a };    }  }  return null;}function personelListesiniCiz(filtre = "") {  const ul = document.getElementById('personelListesi');  if (ul) ul.innerHTML = "";  let filtrelenmis = personeller.filter(p => p.adSoyad.toLowerCase().includes(filtre.toLowerCase()));  filtrelenmis.forEach(p => {    let li = document.createElement('li');    li.className = "personel-item";    let strId = String(p.id);    let isChecked = seciliPersonelIds.has(strId) ? "checked" : "";    li.innerHTML = `      <input type="checkbox" ${isChecked} onclick="event.stopPropagation(); personelSecimToggle('${strId}', this)">      <span class="personel-name">${p.adSoyad}</span>      <span class="arrow">&gt;</span>    `;    li.onclick = () => personelDetayAc(strId);    if (ul) ul.appendChild(li);  });  let countEl = document.getElementById('toplamPersonelSayisi');  if (countEl) countEl.innerText = `Toplam: ${personeller.length} Kişi`;  seciliSayisiniGuncelle();}function personelDetayAc(id, isRestore = false) {  aktifPersonelId = String(id);  let p = personeller.find(x => String(x.id) === aktifPersonelId);  if(!p) return;  let container = document.getElementById('kategoriListesi');  if(!container) return;  container.innerHTML = "";  let anaKategoriler = Object.keys(sablon);  if (anaKategoriler.length === 0) {    container.innerHTML = `      <div style="text-align:center; color:#666; padding: 30px 10px; background: white; border-radius: 12px; border: 1px dashed #ccc;">        <p style="margin-bottom: 10px; font-weight: bold;">Henüz tanımlı bir şablon/menü bulunmuyor.</p>        <small style="color:#888;">Sağ üstteki ⚙️ Ayarlar menüsünden kategori ve alanlar ekleyebilirsiniz.</small>      </div>    `;  } else {    anaKategoriler.forEach(k1 => {      let box = document.createElement('div');      box.style.cssText = "background: #f8f9fa; border: 1px solid #e9ecef; border-radius: 10px; margin-bottom: 12px; padding: 12px; width: 100%;";      let altHtml = "";      Object.keys(sablon[k1]).forEach(k2 => {        altHtml += `          <div onclick="formEkraniAc('${k1}', '${k2}')" style="display: flex; justify-content: space-between; align-items: center; padding: 10px 0; border-bottom: 1px solid #eee; cursor: pointer;">            <span style="font-size: 14px; color: #495057;">• ${k2}</span>            <span style="color: #aaa; font-weight: bold;">&gt;</span>          </div>        `;      });      box.innerHTML = `        <div style="font-weight: bold; color: #1e88e5; font-size: 15px; margin-bottom: 6px;">📂 ${k1}</div>        ${altHtml || '<div style="font-size: 12px; color: #999;">Alt başlık yok</div>'}      `;      container.appendChild(box);    });  }  if (!isRestore) {    gorselKategoriEkraniGoster(true);  }}function formEkraniAc(k1, k2, isRestore = false) {  aktifAnaKategori = k1;  aktifAltKategori = k2;  sessionStorage.setItem('appState', JSON.stringify({ ekran: 'form', personelId: aktifPersonelId, k1: k1, k2: k2 }));  let vCat = document.getElementById('viewCategories');  if (vCat) vCat.style.display = 'none';  let vForm = document.getElementById('viewForm');  if (vForm) vForm.style.display = 'block';  let ht = document.getElementById('headerTitle');  if (ht) ht.innerText = k2;  let btnBack = document.getElementById('btnBack');  if (btnBack) btnBack.style.visibility = "visible";  let btnSettings = document.getElementById('btnSettings');  if (btnSettings) btnSettings.style.visibility = "hidden";  let alanlar = (sablon[k1] && sablon[k1][k2]) ? sablon[k1][k2] : [];  let p = personeller.find(x => String(x.id) === String(aktifPersonelId));  let mainKey = `${k1}_${k2}`;  let kayitliVeri = (p && p.veriler && p.veriler[mainKey] && p.veriler[mainKey][0]) ? p.veriler[mainKey][0] : {};  let container = document.getElementById('formContainer');  if (container) {    container.innerHTML = "";    if (alanlar.length === 0) {      container.innerHTML = `        <div style="text-align:center; color:#666; padding: 20px 10px;">          <p style="margin-bottom: 10px;">Bu menünün altında henüz veri alanı bulunmuyor.</p>          <small style="color:#999;">Ayarlar menüsünden bu kategoriye alanlar ekleyebilirsiniz.</small>        </div>      `;    } else {      alanlar.forEach(alan => {        let val = kayitliVeri[alan] || "";        let placeholderText = "Değer girin...";        let alanKucuk = alan.toLowerCase();        if (alanKucuk.includes('telefon') || alanKucuk.includes('tel')) {          placeholderText = "örn. 05554443322";        } else if (alanKucuk.includes('tarih') || alanKucuk.includes('dogum')) {          placeholderText = "örn. 15.08.1990";        } else if (alanKucuk.includes('tc') || alanKucuk.includes('kimlik')) {          placeholderText = "örn. 12345678901";        }        let group = document.createElement('div');        group.className = "form-group";        group.innerHTML = `          <label>${alan}</label>          <input type="text" data-field="${alan}" value="${val}" placeholder="${placeholderText}">        `;        container.appendChild(group);      });    }  }  if (!isRestore) {    history.pushState({ ekran: 'form', personelId: aktifPersonelId, k1: k1, k2: k2 }, "");  }}function verileriKaydet() {  let p = personeller.find(x => String(x.id) === String(aktifPersonelId));  if (!p) return;  if (!p.veriler) p.veriler = {};  let mainKey = `${aktifAnaKategori}_${aktifAltKategori}`;  let formData = {};  let inputs = document.querySelectorAll('#formContainer input');  if (inputs.length === 0) {    return özelBildirimGoster("Kaydedilecek bir veri alanı bulunmuyor.");  }  inputs.forEach(inp => {    formData[inp.getAttribute('data-field')] = inp.value;  });  p.veriler[mainKey] = [formData];  kaydetLocal();  özelBildirimGoster("Form verileri cihaz hafızasına kaydedildi.");  let vForm = document.getElementById('viewForm');  if (vForm) vForm.style.display = 'none';  let vCat = document.getElementById('viewCategories');  if (vCat) vCat.style.display = 'block';  let ht = document.getElementById('headerTitle');  if (ht) ht.innerText = p.adSoyad;  let btnBack = document.getElementById('btnBack');  if (btnBack) btnBack.style.visibility = "visible";  let btnSettings = document.getElementById('btnSettings');  if (btnSettings) btnSettings.style.visibility = "hidden";  sessionStorage.setItem('appState', JSON.stringify({ ekran: 'categories', personelId: aktifPersonelId }));}function personelAra() {  let q = "";  let searchInput = document.getElementById('searchInput');  if (searchInput) q = searchInput.value.toLowerCase().trim();  const ul = document.getElementById('personelListesi');  if (ul) ul.innerHTML = "";  let filtrelenmis = personeller.filter(p => {    if (p.adSoyad.toLowerCase().includes(q) || String(p.id).toLowerCase().includes(q)) {      return true;    }    if (p.veriler) {      for (let mainKey in p.veriler) {        let kayitlar = p.veriler[mainKey];        if (Array.isArray(kayitlar)) {          for (let kayit of kayitlar) {            for (let alan in kayit) {              let deger = String(kayit[alan] || '').toLowerCase();              if (deger.includes(q)) {                return true;              }            }          }        }      }    }    return false;  });  filtrelenmis.forEach(p => {    let li = document.createElement('li');    li.className = "personel-item";    let strId = String(p.id);    let isChecked = seciliPersonelIds.has(strId) ? "checked" : "";    let eslesmeEtiketi = "";    if (q.length > 0 && !p.adSoyad.toLowerCase().includes(q) && !String(p.id).toLowerCase().includes(q)) {      for (let mainKey in p.veriler) {        let kayitlar = p.veriler[mainKey];        if (Array.isArray(kayitlar)) {          for (let kayit of kayitlar) {            for (let alan in kayit) {              let val = String(kayit[alan] || '');              if (val.toLowerCase().includes(q)) {                eslesmeEtiketi = `<span style="font-size:11px; color:#1e88e5; background:#e3f2fd; padding:2px 6px; border-radius:4px; margin-left:8px;">${alan}: ${val}</span>`;                break;              }            }          }          if (eslesmeEtiketi) break;        }      }    }    li.innerHTML = `      <input type="checkbox" ${isChecked} onclick="event.stopPropagation(); personelSecimToggle('${strId}', this)">      <div style="flex:1; display:flex; flex-direction:column;">        <span class="personel-name">${p.adSoyad}</span>        ${eslesmeEtiketi}      </div>      <span class="arrow">&gt;</span>    `;    li.onclick = () => personelDetayAc(strId);    if (ul) ul.appendChild(li);  });  let tps = document.getElementById('toplamPersonelSayisi');  if (tps) tps.innerText = `Gösterilen: ${filtrelenmis.length} / Toplam: ${personeller.length} Kişi`;  seciliSayisiniGuncelle();}function personelSecimToggle(id, checkbox) {  let strId = String(id);  if (checkbox.checked) {    seciliPersonelIds.add(strId);  } else {    seciliPersonelIds.delete(strId);  }  seciliSayisiniGuncelle();}function hepsiniSecToggle(checkbox) {  let searchInput = document.getElementById('searchInput');  let filtre = searchInput ? searchInput.value : "";  let filtrelenmis = personeller.filter(p => p.adSoyad.toLowerCase().includes(filtre.toLowerCase()));  if (checkbox.checked) {    filtrelenmis.forEach(p => seciliPersonelIds.add(String(p.id)));  } else {    filtrelenmis.forEach(p => seciliPersonelIds.delete(String(p.id)));  }  personelListesiniCiz(filtre);}function seciliSayisiniGuncelle() {  let ss = document.getElementById('seciliSayisi');  if (ss) ss.innerText = seciliPersonelIds.size;  let searchInput = document.getElementById('searchInput');  let filtre = searchInput ? searchInput.value : "";  let filtrelenmis = personeller.filter(p => p.adSoyad.toLowerCase().includes(filtre.toLowerCase()));  let allFilteredSelected = filtrelenmis.length > 0 && filtrelenmis.every(p => seciliPersonelIds.has(String(p.id)));  let selectAllCb = document.getElementById('selectAllCheckbox');  if (selectAllCb) selectAllCb.checked = allFilteredSelected;}function yeniPersonelEkle() {  const modal = document.createElement('div');  modal.style.cssText = `    position: fixed; top: 0; left: 0; width: 100%; height: 100%;    background: rgba(0,0,0,0.5); display: flex; align-items: center;    justify-content: center; z-index: 9999;  `;  modal.innerHTML = `    <div style="background:white; width:85%; max-width:340px; padding:20px; border-radius:14px; box-shadow:0 4px 20px rgba(0,0,0,0.25);">      <h3 style="margin-top:0; color:#1e88e5;">➕ Yeni Personel</h3>      <input id="yeniPersonelInput" type="text" placeholder="Adı Soyadı" style="width:100%; padding:10px; border:1px solid #ccc; border-radius:8px; font-size:14px; margin-top:8px; box-sizing: border-box;">      <input id="yeniSicilInput" type="text" inputmode="numeric" pattern="[0-9]*" placeholder="6 Haneli Sicil No (ID)" style="width:100%; padding:10px; border:1px solid #ccc; border-radius:8px; font-size:14px; margin-top:10px; box-sizing: border-box;">      <div style="display:flex; justify-content:flex-end; gap:10px; margin-top:18px;">        <button id="iptalBtn" style="background:#999; color:white; border:none; padding:10px 16px; border-radius:8px; font-weight:bold; cursor:pointer;">İptal</button>        <button id="kaydetBtn" style="background:#00897b; color:white; border:none; padding:10px 16px; border-radius:8px; font-weight:bold; cursor:pointer;">Kaydet</button>      </div>    </div>  `;  document.body.appendChild(modal);  const isimInput = modal.querySelector('#yeniPersonelInput');  const sicilInput = modal.querySelector('#yeniSicilInput');  isimInput.focus();  modal.querySelector('#iptalBtn').onclick = () => modal.remove();  modal.querySelector('#kaydetBtn').onclick = () => {    const isim = isimInput.value.trim();    const sicilNo = sicilInput.value.trim();    if (!isim) { isimInput.focus(); return; }    if (!sicilNo || sicilNo.length < 3) {      özelBildirimGoster("Lütfen geçerli bir sicil numarası girin.");      sicilInput.focus();      return;    }    const cakisanPersonel = personeller.find(p => String(p.id) === sicilNo);    if (cakisanPersonel) {      özelBildirimGoster(`Bu sicil numarası zaten "${cakisanPersonel.adSoyad}" adına kayıtlı!`);      return;    }    personeller.push({ id: sicilNo, adSoyad: isim, veriler: {} });    kaydetLocal();    personelListesiniCiz();    modal.remove();    özelBildirimGoster(`"${isim}" personeli eklendi.`);  };}function secilileriSil() {  if (seciliPersonelIds.size === 0) {    return özelBildirimGoster("Lütfen silinecek en az bir personel seçin!");  }  if (confirm(`${seciliPersonelIds.size} kişiyi silmek istediğinizden emin misiniz?`)) {    personeller = personeller.filter(p => !seciliPersonelIds.has(String(p.id)));    seciliPersonelIds.clear();    kaydetLocal();    personelListesiniCiz();  }}function whatsappKonumIste() {  if (seciliPersonelIds.size === 0) {    return özelBildirimGoster("Lütfen konum istemek için en az bir personel seçin!");  }  let seciliId = Array.from(seciliPersonelIds)[0];  let p = personeller.find(x => String(x.id) === String(seciliId));  let tel = personelAsilTelefonunuBul(p);  if (!tel) {    return özelBildirimGoster(`${p.adSoyad} isimli personelin şahsi telefon numarası kayıtlarda bulunamadı!`);  }  let temizTel = tel.replace(/\D/g, '');  if (temizTel.startsWith('0') && temizTel.length === 11) {    temizTel = '90' + temizTel.substring(1);  } else if (temizTel.length === 10) {    temizTel = '90' + temizTel;  }  let mesaj = encodeURIComponent(`Merhaba ${p.adSoyad}, lütfen güncel canlı konumunuzu bu sohbet üzerinden paylaşabilir misiniz?`);  const whatsappUrl = 'https://wa.me/' + temizTel + '?text=' + mesaj;  try {    window.open(whatsappUrl, '_blank');  } catch (e) {    özelBildirimGoster("WhatsApp açılamadı. Lütfen tarayıcınızın pop-up engelleyicisini kontrol edin.");  }}function bilgiNotunuKaydet() {  const input = document.getElementById('bilgiNotuInput');  if (input) {    localStorage.setItem('anaSayfaBilgiNotu', input.value);    alert("Bilgi notu başarıyla kaydedildi!");  }}function ayarlarSayfasinaGit() {  let vMain = document.getElementById('viewMain');  if (vMain) vMain.style.display = 'none';    let vAyarlar = document.getElementById('viewAyarlar');  if (vAyarlar) vAyarlar.style.display = 'block';    // Üstteki başlık/bilgi kutusunu tamamen gizler  let cHeader = document.getElementById('cardHeader');  if (cHeader) cHeader.style.display = 'none';  sessionStorage.setItem('aktifSayfa', 'ayarlar');  sablonListesiniCiz();    let kaydedilenNot = localStorage.getItem('anaSayfaBilgiNotu') || '';  let input = document.getElementById('bilgiNotuInput');  if (input) input.value = kaydedilenNot;    history.pushState({ ekran: 'ayarlar' }, "");}function anaSayfayaDon() {  window.history.back();}function sablonListesiniCiz() {  const container = document.getElementById('sablonListesiContainer');  const select = document.getElementById('anaKategoriSecici');  if (!container || !select) return;  container.innerHTML = "";  select.innerHTML = "";  let anaKategoriler = Object.keys(sablon);  if (anaKategoriler.length === 0) {    select.innerHTML = '<option value="">Önce ana kategori ekleyin</option>';    container.innerHTML = '<div style="color: #888; font-style: italic; text-align: center; padding: 10px;">Henüz kategori eklenmemiş.</div>';    return;  }  anaKategoriler.forEach(k1 => {    let opt = document.createElement('option');    opt.value = k1;    opt.innerText = k1;    select.appendChild(opt);    let catBox = document.createElement('div');    catBox.style.cssText = "background: #f9f9f9; padding: 8px; border-radius: 6px; margin-bottom: 8px; border: 1px solid #e0e0e0;";    let altKategorilerHtml = "";    Object.keys(sablon[k1]).forEach(k2 => {      let alanlar = sablon[k1][k2] || [];      let alanlarHtml = alanlar.map(alan => `        <span style="display:inline-flex; align-items:center; background:#e0e0e0; padding:3px 8px; border-radius:6px; margin-right:4px; margin-bottom:4px; border:1px solid #ccc; font-size: 11px;">          ${alan}          <button onclick="alanDuzenle('${k1}', '${k2}', '${alan}')" style="background:none; border:none; color:#1e88e5; cursor:pointer; font-size:12px; margin-left:6px; padding:0;" title="Düzenle">✏️</button>          <button onclick="alanSil('${k1}', '${k2}', '${alan}')" style="background:none; border:none; color:#e53935; cursor:pointer; font-size:12px; margin-left:6px; padding:0;" title="Sil">❌</button>        </span>      `).join("");      let alanlarText = alanlar.length > 0 ? `<div style="margin-top:4px; display:flex; flex-wrap:wrap;">${alanlarHtml}</div>` : "<div style='color:#999; margin-top:2px; font-size: 11px;'>Alan yok</div>";      altKategorilerHtml += `        <div style="margin-left: 10px; margin-top: 6px; padding-top: 4px; border-top: 1px dashed #ddd;">          <div style="display: flex; justify-content: space-between; align-items: center;">            <span style="font-weight: 600; font-size: 13px;">• ${k2}</span>            <div style="display:flex; gap: 6px;">              <button onclick="altKategoriDuzenle('${k1}', '${k2}')" style="background: #1e88e5; border: none; color: white; cursor: pointer; font-size: 10px; padding: 3px 6px; border-radius: 4px;">Düzenle</button>              <button onclick="altKategoriSil('${k1}', '${k2}')" style="background: #e53935; border: none; color: white; cursor: pointer; font-size: 10px; padding: 3px 6px; border-radius: 4px;">Sil</button>            </div>          </div>          <div>${alanlarText}</div>          <button onclick="alanEkle('${k1}', '${k2}')" style="background: #00897b; color: white; border: none; padding: 3px 10px; border-radius: 4px; font-size: 10px; margin-top: 8px; cursor: pointer;">+ Alan Ekle</button>        </div>      `;    });    catBox.innerHTML = `      <div style="display: flex; justify-content: space-between; align-items: center; font-weight: bold; color: #1e88e5;">        <span>📂 ${k1}</span>        <div style="display:flex; gap: 6px;">          <button onclick="anaKategoriDuzenle('${k1}')" style="background: #1e88e5; border: none; color: white; cursor: pointer; font-size: 11px; padding: 4px 8px; border-radius: 4px;">Düzenle</button>          <button onclick="anaKategoriSil('${k1}')" style="background: #e53935; border: none; color: white; cursor: pointer; font-size: 11px; padding: 4px 8px; border-radius: 4px;">Sil</button>        </div>      </div>      ${altKategorilerHtml}    `;    container.appendChild(catBox);  });}function anaKategoriDuzenle(eskiAd) {  let yeniAd = prompt("Yeni ana kategori adını girin:", eskiAd);  if (!yeniAd || yeniAd.trim() === "" || yeniAd === eskiAd) return;  yeniAd = yeniAd.trim();  if (sablon[yeniAd]) return özelBildirimGoster("Bu isimde bir ana kategori zaten var.");  sablon[yeniAd] = sablon[eskiAd];  delete sablon[eskiAd];  personeller.forEach(p => {    if (p.veriler) {      Object.keys(sablon[yeniAd]).forEach(k2 => {        let eskiKey = `${eskiAd}_${k2}`;        let yeniKey = `${yeniAd}_${k2}`;        if (p.veriler[eskiKey]) {          p.veriler[yeniKey] = p.veriler[eskiKey];          delete p.veriler[eskiKey];        }      });    }  });  kaydetLocal();  sablonListesiniCiz();  özelBildirimGoster("Ana kategori adı başarıyla güncellendi.");}function altKategoriDuzenle(k1, eskiAd) {  let yeniAd = prompt("Yeni alt kategori adını girin:", eskiAd);  if (!yeniAd || yeniAd.trim() === "" || yeniAd === eskiAd) return;  yeniAd = yeniAd.trim();  if (sablon[k1][yeniAd]) return özelBildirimGoster("Bu isimde bir alt kategori zaten var.");  sablon[k1][yeniAd] = sablon[k1][eskiAd];  delete sablon[k1][eskiAd];  let eskiKey = `${k1}_${eskiAd}`;  let yeniKey = `${k1}_${yeniAd}`;  personeller.forEach(p => {    if (p.veriler && p.veriler[eskiKey]) {      p.veriler[yeniKey] = p.veriler[eskiKey];      delete p.veriler[eskiKey];    }  });  kaydetLocal();  sablonListesiniCiz();  özelBildirimGoster("Alt kategori adı başarıyla güncellendi.");}function alanDuzenle(k1, k2, eskiAd) {  let yeniAd = prompt("Yeni alan adını girin:", eskiAd);  if (!yeniAd || yeniAd.trim() === "" || yeniAd === eskiAd) return;  yeniAd = yeniAd.trim();  let index = sablon[k1][k2].indexOf(eskiAd);  if (index === -1) return;  if (sablon[k1][k2].includes(yeniAd)) return özelBildirimGoster("Bu isimde bir alan zaten var.");  sablon[k1][k2][index] = yeniAd;  let mainKey = `${k1}_${k2}`;  personeller.forEach(p => {    if (p.veriler && p.veriler[mainKey]) {      p.veriler[mainKey].forEach(kayit => {        if (kayit[eskiAd] !== undefined) {          kayit[yeniAd] = kayit[eskiAd];          delete kayit[eskiAd];        }      });    }  });  kaydetLocal();  sablonListesiniCiz();  özelBildirimGoster("Alan adı başarıyla güncellendi.");}function alanSil(k1, k2, alanAd) {  if (confirm(`'${alanAd}' alanını silmek istediğinize emin misiniz?`)) {    sablon[k1][k2] = sablon[k1][k2].filter(a => a !== alanAd);    let mainKey = `${k1}_${k2}`;    personeller.forEach(p => {      if (p.veriler && p.veriler[mainKey]) {        p.veriler[mainKey].forEach(kayit => {          if (kayit[alanAd] !== undefined) {            delete kayit[alanAd];          }        });      }    });    kaydetLocal();    sablonListesiniCiz();  }}function anaKategoriEkle() {  let val = document.getElementById('yeniAnaKategoriInput').value.trim();  if (!val) return özelBildirimGoster("Lütfen bir kategori adı yazın.");  if (sablon[val]) return özelBildirimGoster("Bu kategori zaten var.");  sablon[val] = {};  document.getElementById('yeniAnaKategoriInput').value = "";  kaydetLocal();  sablonListesiniCiz();}function altKategoriEkle() {  let k1 = document.getElementById('anaKategoriSecici').value;  let val = document.getElementById('yeniAltKategoriInput').value.trim();  if (!k1) return özelBildirimGoster("Önce bir ana kategori seçin veya ekleyin.");  if (!val) return özelBildirimGoster("Lütfen alt kategori adı yazın.");  if (sablon[k1][val]) return özelBildirimGoster("Bu alt kategori zaten var.");  sablon[k1][val] = [];   document.getElementById('yeniAltKategoriInput').value = "";  kaydetLocal();  sablonListesiniCiz();}function alanEkle(k1, k2) {  const modal = document.createElement('div');  modal.style.cssText = `    position: fixed; top: 0; left: 0; width: 100%; height: 100%;    background: rgba(0,0,0,0.5); display: flex; align-items: flex-start;    justify-content: center; padding-top: 15vh; z-index: 9999;    overflow-y: auto;  `;  modal.innerHTML = `    <div style="background:white; width:90%; max-width:340px; padding:20px; border-radius:14px; box-shadow:0 4px 20px rgba(0,0,0,0.25);">      <h3 style="margin-top:0; color:#00897b;">➕ Yeni Alan</h3>      <div style="font-size:13px; color:#666; margin-bottom:10px;">${k2} altına eklenecek alan adı</div>      <input id="yeniAlanInput" type="text" placeholder="Örn: Eş Doğum Tarihi" style="width:100%; padding:10px; border:1px solid #ccc; border-radius:8px; font-size:14px; box-sizing:border-box;">      <div style="display:flex; justify-content:flex-end; gap:10px; margin-top:18px;">        <button id="alanIptalBtn" style="background:#999; color:white; border:none; padding:10px 16px; border-radius:8px; font-weight:bold; cursor:pointer;">İptal</button>        <button id="alanKaydetBtn" style="background:#00897b; color:white; border:none; padding:10px 16px; border-radius:8px; font-weight:bold; cursor:pointer;">Ekle</button>      </div>    </div>  `;  document.body.appendChild(modal);  const input = modal.querySelector('#yeniAlanInput');  setTimeout(() => {    input.focus();    input.scrollIntoView({ behavior: 'smooth', block: 'nearest' });  }, 200);  modal.querySelector('#alanIptalBtn').onclick = () => modal.remove();  modal.querySelector('#alanKaydetBtn').onclick = () => {    const alanAdi = input.value.trim();    if (!alanAdi) { input.focus(); return; }    if (!Array.isArray(sablon[k1][k2])) sablon[k1][k2] = [];    if (sablon[k1][k2].includes(alanAdi)) return özelBildirimGoster("Bu alan zaten eklenmiş.");    sablon[k1][k2].push(alanAdi);    kaydetLocal();    sablonListesiniCiz();    modal.remove();    özelBildirimGoster(`"${alanAdi}" alanı eklendi.`);  };}function anaKategoriSil(k1) {  if (confirm(`'${k1}' kategorisini silmek istediğinize emin misiniz?`)) {    delete sablon[k1];    kaydetLocal();    sablonListesiniCiz();  }}function altKategoriSil(k1, k2) {  if (confirm(`'${k2}' alt başlığını silmek istediğinize emin misiniz?`)) {    delete sablon[k1][k2];    kaydetLocal();    sablonListesiniCiz();  }}function yedekOlustur() {  try {    let yedek = {      personeller: personeller,      sablon: sablon,      tarih: new Date().toLocaleString("tr-TR"),      uygulama: "Tim Bilgileri Mobil"    };    let json = JSON.stringify(yedek, null, 2);    let blob = new Blob([json], { type: "application/json" });    let url = URL.createObjectURL(blob);    let a = document.createElement("a");    a.href = url;    a.download = "tim_bilgileri_yedek.json";    document.body.appendChild(a);    a.click();    setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 1000);    özelBildirimGoster("Tam yedek dosyası (Personeller + Şablonlar) başarıyla indirildi.");  } catch (e) {    özelBildirimGoster("Yedek oluşturulurken hata oluştu: " + e.message);  }}function exportExcel() {  if (typeof XLSX === 'undefined') return özelBildirimGoster("Excel kütüphanesi yüklenemedi. Lütfen internet bağlantınızı kontrol edin.");  if (seciliPersonelIds.size === 0) return özelBildirimGoster("Dışa aktarmak için en az bir personel seçin!");  let anaKategoriler = Object.keys(sablon);  if (anaKategoriler.length === 0) {    return özelBildirimGoster("Dışa aktarılacak kategori bulunmuyor.");  }  const modal = document.createElement('div');  modal.style.cssText = `    position: fixed; top: 0; left: 0; width: 100%; height: 100%;    background: rgba(0,0,0,0.5); display: flex; align-items: center;    justify-content: center; z-index: 9999;  `;  let kategoriCheckboxHtml = '';  anaKategoriler.forEach(k1 => {    kategoriCheckboxHtml += `<div style="font-weight: bold; color: #1e88e5; margin-top: 10px;">📂 ${k1}</div>`;    Object.keys(sablon[k1]).forEach(k2 => {      let mainKey = `${k1}_${k2}`;      kategoriCheckboxHtml += `        <label style="display: flex; align-items: center; gap: 8px; margin-left: 15px; margin-top: 5px; font-size: 13px; cursor: pointer;">          <input type="checkbox" class="excel-kategori-cb" value="${mainKey}" checked style="cursor: pointer;">          ${k2}        </label>      `;    });  });  modal.innerHTML = `    <div style="background:white; width:90%; max-width:380px; max-height:80vh; overflow-y:auto; padding:20px; border-radius:14px; box-shadow:0 4px 20px rgba(0,0,0,0.25);">      <h3 style="margin-top:0; color:#1e88e5; font-size:16px;">📊 Excel'e Aktarılacak Alanlar</h3>      <div style="font-size:12px; color:#666; margin-bottom:10px;">Excel'de görünmesini istediğiniz kategorileri seçin:</div>      <div style="border: 1px solid #eee; padding: 10px; border-radius: 8px; background: #fafafa; margin-bottom: 15px; text-align: left;">        ${kategoriCheckboxHtml}      </div>      <div style="display:flex; justify-content:flex-end; gap:10px;">        <button id="excelIptalBtn" style="background:#999; color:white; border:none; padding:8px 14px; border-radius:8px; font-weight:bold; cursor:pointer;">İptal</button>        <button id="excelOnayBtn" style="background:#00897b; color:white; border:none; padding:8px 14px; border-radius:8px; font-weight:bold; cursor:pointer;">Excel İndir</button>      </div>    </div>  `;  document.body.appendChild(modal);  modal.querySelector('#excelIptalBtn').onclick = () => modal.remove();  modal.querySelector('#excelOnayBtn').onclick = () => {    let secilenMainKeyler = new Set();    modal.querySelectorAll('.excel-kategori-cb:checked').forEach(cb => {      secilenMainKeyler.add(cb.value);    });    if (secilenMainKeyler.size === 0) {      özelBildirimGoster("Lütfen en az bir kategori seçin!");      return;    }    modal.remove();    gercekExcelAktariminiYap(secilenMainKeyler);  };}function gercekExcelAktariminiYap(secilenMainKeyler) {  let maxKayitSayilari = {};  Object.keys(sablon).forEach(k1 => {    Object.keys(sablon[k1]).forEach(k2 => {      let mainKey = `${k1}_${k2}`;      if (!secilenMainKeyler.has(mainKey)) return;      let maxCount = 1;      personeller.forEach(p => {        if (seciliPersonelIds.has(String(p.id)) && p.veriler && p.veriler[mainKey]) {          if (p.veriler[mainKey].length > maxCount) maxCount = p.veriler[mainKey].length;        }      });      maxKayitSayilari[mainKey] = maxCount;    });  });  let sutunHaritasi = [    { header: 'Sicil No', isStatic: true, key: 'id' },    { header: 'Adı Soyadı', isStatic: true, key: 'adSoyad' }  ];  Object.keys(sablon).forEach(k1 => {    Object.keys(sablon[k1]).forEach(k2 => {      let mainKey = `${k1}_${k2}`;      if (!secilenMainKeyler.has(mainKey)) return;      let alanlar = sablon[k1][k2] || [];      let tekrarSayisi = maxKayitSayilari[mainKey] || 1;      for (let i = 0; i < tekrarSayisi; i++) {        alanlar.forEach(alan => {          let baslikSuffix = tekrarSayisi > 1 ? ` ${i + 1}` : '';          sutunHaritasi.push({ header: `${alan}${baslikSuffix} (${k1} > ${k2})`, mainKey: mainKey, index: i, alan: alan });        });      }    });  });  let excelMatris = [];  excelMatris.push(sutunHaritasi.map(s => s.header));  personeller.forEach(p => {    if (seciliPersonelIds.has(String(p.id))) {      let satir = [];      sutunHaritasi.forEach(s => {        if (s.isStatic) {          let val = p[s.key];          satir.push(val !== undefined && val !== null ? val : '');        } else {          let kayitListesi = p.veriler ? p.veriler[s.mainKey] : null;          if (kayitListesi && kayitListesi[s.index] && kayitListesi[s.index][s.alan] !== undefined) {            let val = kayitListesi[s.index][s.alan];            if (Array.isArray(val)) {              satir.push(val.join(', '));            } else if (typeof val === 'object' && val !== null) {              satir.push(val.ad || val.isim || JSON.stringify(val));            } else {              satir.push(val);            }          } else {            satir.push('');          }        }      });      excelMatris.push(satir);    }  });  let ws = XLSX.utils.aoa_to_sheet(excelMatris);  ws['!cols'] = sutunHaritasi.map(s => {      if (s.isStatic) {          return { wch: s.key === 'id' ? 12 : 22 };       }      let baslikUzunlugu = s.header ? s.header.length : 15;      return { wch: Math.min(Math.max(baslikUzunlugu + 2, 15), 28) };  });  let wb = XLSX.utils.book_new();  XLSX.utils.book_append_sheet(wb, ws, "Personel Listesi");  try {    const excelBuffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });    const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });    const url = URL.createObjectURL(blob);    let a = document.createElement('a');    a.href = url;    a.download = 'Personel_Secmeli_Liste.xlsx';    document.body.appendChild(a);    a.click();    setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 1000);    özelBildirimGoster('Seçilen kategoriler ile Excel dosyası indirildi.');  } catch(e) {    özelBildirimGoster('Dışa aktarma hatası: ' + e.message);  }}function importExcel(event) {  if (typeof XLSX === 'undefined') return özelBildirimGoster("Excel kütüphanesi yüklenemedi.");  let file = event.target.files[0];  if (!file) return;  let reader = new FileReader();  reader.onload = function(e) {    try {      let data = new Uint8Array(e.target.result);      let workbook = XLSX.read(data, { type: 'array' });      let firstSheetName = workbook.SheetNames[0];      let worksheet = workbook.Sheets[firstSheetName];      let json = XLSX.utils.sheet_to_json(worksheet, { header: 1 });      if (json.length < 2) return özelBildirimGoster("Dosya boş veya geçersiz format.");      let basliklar = json[0];      let eklenenSayisi = 0;      let guncellenenSayisi = 0;      let adSoyadIndex = basliklar.findIndex(b => b && b.toString().trim().toLowerCase().includes('ad'));      let idIndex = basliklar.findIndex(b => b && (['id', 'sicil no', 'personel kodu'].includes(b.toString().trim().toLowerCase())));      if (adSoyadIndex === -1) adSoyadIndex = 1;      basliklar.forEach((baslik, colIdx) => {        if (colIdx === idIndex || colIdx === adSoyadIndex || !baslik) return;        let match = baslik.toString().match(/(.*)\((.*)\)/);        if (match) {          let hamAlanAdi = match[1].trim();          let icerik = match[2].trim();          let alanAdi = hamAlanAdi.replace(/\s+\d+$/, '').trim();          let anaKat = null;          let altKat = null;          if (icerik.includes('>')) {            let parcalar = icerik.split('>');            anaKat = parcalar[0].trim();            altKat = parcalar[1].trim();          } else {            altKat = icerik;            Object.keys(sablon).forEach(k1 => { if (sablon[k1][altKat]) anaKat = k1; });            if (!anaKat) {              if (!sablon['Genel Bilgiler']) sablon['Genel Bilgiler'] = {};              anaKat = 'Genel Bilgiler';            }          }          if (!sablon[anaKat]) sablon[anaKat] = {};          if (!sablon[anaKat][altKat]) sablon[anaKat][altKat] = [];          if (!sablon[anaKat][altKat].includes(alanAdi)) sablon[anaKat][altKat].push(alanAdi);        }      });      for (let i = 1; i < json.length; i++) {        let satir = json[i];        if (!satir || satir.length === 0) continue;        let adSoyadVal = satir[adSoyadIndex] ? satir[adSoyadIndex].toString().trim() : '';        if (!adSoyadVal) continue;        let excelId = (idIndex !== -1 && satir[idIndex]) ? String(satir[idIndex]) : null;        let mevcutPersonel = personeller.find(p => p.adSoyad.toLowerCase() === adSoyadVal.toLowerCase());        if (!mevcutPersonel) {          let idCakismasiVarMi = excelId && personeller.some(p => String(p.id) === excelId);          let atanacakId = (excelId && !idCakismasiVarMi) ? excelId : String(Date.now() + i);          mevcutPersonel = { id: atanacakId, adSoyad: adSoyadVal, veriler: {} };          personeller.push(mevcutPersonel);          eklenenSayisi++;        } else {          guncellenenSayisi++;        }        basliklar.forEach((baslik, colIdx) => {          if (colIdx === idIndex || colIdx === adSoyadIndex || !baslik) return;          let val = satir[colIdx] !== undefined ? satir[colIdx].toString().trim() : '';          if (!val) return;          let match = baslik.toString().match(/(.*)\((.*)\)/);          if (match) {            let hamAlanAdi = match[1].trim();            let icerik = match[2].trim();            let alanAdi = hamAlanAdi.replace(/\s+\d+$/, '').trim();            let anaKat = null;            let altKat = null;            if (icerik.includes('>')) {              let parcalar = icerik.split('>');              anaKat = parcalar[0].trim();              altKat = parcalar[1].trim();            } else {              altKat = icerik;              Object.keys(sablon).forEach(k1 => { if (sablon[k1][altKat]) anaKat = k1; });              if (!anaKat) anaKat = 'Genel Bilgiler';            }            if (sablon[anaKat] && sablon[anaKat][altKat]) {              let mainKey = `${anaKat}_${altKat}`;              if (!mevcutPersonel.veriler) mevcutPersonel.veriler = {};              if (!mevcutPersonel.veriler[mainKey]) mevcutPersonel.veriler[mainKey] = [{}];              mevcutPersonel.veriler[mainKey][0][alanAdi] = val;            }          }        });      }      kaydetLocal();      personelListesiniCiz();      ozelGunleriKontrolEtVeGoster();      event.target.value = '';      özelBildirimGoster(`${eklenenSayisi} yeni personel eklendi, ${guncellenenSayisi} personel güncellendi.\nKategoriler Excel'den başarıyla geri yüklendi.`);    } catch (err) {      özelBildirimGoster("Excel işlenirken hata oluştu: " + err.message);    }  };  reader.readAsArrayBuffer(file);}function zimmetTakipPaneliAc() {  const modal = document.createElement('div');  modal.style.cssText = `    position: fixed; top: 0; left: 0; width: 100%; height: 100%;    background: rgba(0,0,0,0.5); display: flex; align-items: center;    justify-content: center; z-index: 9999;  `;  let icerikHtml = '';  let kategoriSecenekleri = '';  Object.keys(sablon).forEach(k1 => {    Object.keys(sablon[k1]).forEach(k2 => {      kategoriSecenekleri += `<option value="${k1}_${k2}">${k1} > ${k2}</option>`;    });  });  modal.innerHTML = `    <div style="background:white; width:95%; max-width:480px; max-height:85vh; overflow-y:auto; padding:20px; border-radius:14px; box-shadow:0 4px 20px rgba(0,0,0,0.25);">      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">        <h3 style="margin:0; color:#1e88e5; font-size:16px;">📦 Kapsamlı Zimmet ve Takip Paneli</h3>        <button onclick="this.parentElement.parentElement.parentElement.remove()" style="background:none; border:none; font-size:18px; cursor:pointer;">✕</button>      </div>      <div style="font-size:12px; color:#666; margin-bottom:8px;">Takip etmek istediğiniz şablon alt kategorisini seçin:</div>      <div style="display:flex; gap:6px; margin-bottom:12px;">        <select id="takipKategoriSecici" style="flex:1; padding:8px; border:1px solid #ccc; border-radius:6px; font-size:13px;">          ${kategoriSecenekleri || '<option>Önce şablon oluşturun</option>'}        </select>        <button onclick="zimmetRaporuGetir()" style="background:#1e88e5; color:white; border:none; padding:8px 12px; border-radius:6px; font-weight:bold; cursor:pointer; font-size:13px;">Listele</button>      </div>      <div id="zimmetRaporSonuc" style="border:1px solid #eee; background:#fafafa; padding:10px; border-radius:8px; max-height:300px; overflow-y:auto; font-size:13px;">        <div style="text-align:center; color:#888; padding:20px;">Lütfen bir kategori seçip Listele butonuna basın.</div>      </div>      <div style="display:flex; justify-content:flex-end; margin-top:15px;">        <button onclick="this.parentElement.parentElement.parentElement.remove()" style="background:#333; color:white; border:none; padding:8px 16px; border-radius:8px; font-weight:bold; cursor:pointer;">Kapat</button>      </div>    </div>  `;  document.body.appendChild(modal);}function zimmetRaporuGetir() {  let select = document.getElementById('takipKategoriSecici');  let sonucContainer = document.getElementById('zimmetRaporSonuc');  if (!select || !sonucContainer) return;  let mainKey = select.value;  if (!mainKey) return;  let [k1, k2] = mainKey.split('_');  let alanlar = (sablon[k1] && sablon[k1][k2]) ? sablon[k1][k2] : [];  let listeHtml = '';  let kayitSayisi = 0;  personeller.forEach(p => {    if (p.veriler && p.veriler[mainKey] && Array.isArray(p.veriler[mainKey])) {      p.veriler[mainKey].forEach(kayit => {        let doluMu = Object.values(kayit.hasOwnProperty('length') ? kayit : Object.values(kayit)).some(val => val && val.toString().trim() !== '');        if (doluMu) {          kayitSayisi++;          let detaylar = alanlar.map(alan => `<b>${alan}:</b> ${kayit[alan] || '-'}`).join(' | ');          listeHtml += `            <div style="padding:8px; border-bottom:1px solid #eee; background:white; border-radius:6px; margin-bottom:6px;">              <div style="font-weight:bold; color:#333; margin-bottom:2px;">👤 ${p.adSoyad} <span style="font-size:11px; color:#666;">(Sicil: ${p.id})</span></div>              <div style="font-size:12px; color:#555;">${detaylar}</div>            </div>          `;        }      });    }  });  if (kayitSayisi === 0) {    sonucContainer.innerHTML = `<div style="text-align:center; color:#888; padding:20px;">Bu kategoride henüz kayıt girilmiş bir veri bulunmuyor.</div>`;  } else {    sonucContainer.innerHTML = `<div style="font-size:12px; color:#444; margin-bottom:8px; font-weight:bold;">Toplam ${kayitSayisi} kayıt bulundu:</div>` + listeHtml;  }}function veriYonetimiMenuAc() {  const modal = document.createElement('div');  modal.style.cssText = `    position: fixed; top: 0; left: 0; width: 100%; height: 100%;    background: rgba(0,0,0,0.5); display: flex; align-items: center;    justify-content: center; z-index: 9999; animation: fadeIn 0.2s ease;  `;  modal.innerHTML = `    <div style="background:white; width:90%; max-width:360px; padding:20px; border-radius:14px; box-shadow:0 4px 20px rgba(0,0,0,0.25);">      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:15px; border-bottom:1px solid #eee; padding-bottom:10px;">        <h3 style="margin:0; color:#673ab7; font-size:16px;">📁 Veri ve Yedek Yönetimi</h3>        <button onclick="this.parentElement.parentElement.parentElement.remove()" style="background:none; border:none; font-size:20px; cursor:pointer; color:#666;">✕</button>      </div>      <div style="display:flex; flex-direction:column; gap:10px;">        <button onclick="this.parentElement.parentElement.parentElement.remove(); jsonVeritabaninaKaydet();" style="background:#ff5722; color:white; border:none; padding:12px; border-radius:8px; font-weight:bold; cursor:pointer; text-align:left; display:flex; align-items:center; gap:8px; font-size:13px;">          💾 Cihaz Hafızasına Kaydet        </button>        <button onclick="this.parentElement.parentElement.parentElement.remove(); yedekOlustur();" style="background:#43a047; color:white; border:none; padding:12px; border-radius:8px; font-weight:bold; cursor:pointer; text-align:left; display:flex; align-items:center; gap:8px; font-size:13px;">          🗄️ Tam Yedek Al (JSON)        </button>        <button onclick="this.parentElement.parentElement.parentElement.remove(); dosyaSeciciAc();" style="background:#673ab7; color:white; border:none; padding:12px; border-radius:8px; font-weight:bold; cursor:pointer; text-align:left; display:flex; align-items:center; gap:8px; font-size:13px;">          ♻️ Yedekten Geri Yükle (JSON)        </button>        <button onclick="this.parentElement.parentElement.parentElement.remove(); exportExcel();" style="background:#2e7d32; color:white; border:none; padding:12px; border-radius:8px; font-weight:bold; cursor:pointer; text-align:left; display:flex; align-items:center; gap:8px; font-size:13px;">          📊 Seçilileri Excel'e Aktar (xlsx)        </button>        <button onclick="this.parentElement.parentElement.parentElement.remove(); document.getElementById('excelInput').click();" style="background:#3f51b5; color:white; border:none; padding:12px; border-radius:8px; font-weight:bold; cursor:pointer; text-align:left; display:flex; align-items:center; gap:8px; font-size:13px;">          📥 Excel'den İçeri Al (xlsx)        </button>      </div>      <button onclick="this.parentElement.parentElement.remove()" style="background:#999; color:white; border:none; padding:10px; border-radius:8px; font-weight:bold; cursor:pointer; width:100%; margin-top:15px;">Kapat</button>    </div>  `;  document.body.appendChild(modal);}// --- NÖBET VE İSTATİSTİK MODÜLÜ ---function nobetVerileriniGetir() {  try { return JSON.parse(localStorage.getItem('nobetKayitlari')) || []; }   catch (e) { return []; }}function nobetVerileriniKaydet(kayitlar) {  localStorage.setItem('nobetKayitlari', JSON.stringify(kayitlar));}function parseSaatAraligi(aralikStr) {  if (!aralikStr || !aralikStr.includes('-')) return { startMin: 0, endMin: 0 };  let parcalar = aralikStr.split('-');  let baslangic = parcalar[0].trim().replace('.', ':');  let bitis = parcalar[1].trim().replace('.', ':');  let [basSaat, basDakika] = baslangic.split(':').map(Number);  let [bitSaat, bitDakika] = bitis.split(':').map(Number);  let startMin = ((basSaat || 0) * 60) + (basDakika || 0);  let endMin = ((bitSaat || 0) * 60) + (bitDakika || 0);  if (endMin < startMin) endMin += 24 * 60;  return { startMin, endMin };}function saatAraliginiHesapla(aralikStr) {  let intv = parseSaatAraligi(aralikStr);  let farkDakika = intv.endMin - intv.startMin;  if (farkDakika < 0) farkDakika += 24 * 60;  return farkDakika / 60;}function saatlerCisiyorMu(yeniTarih, yeniAralik, personelId, mevcutKayitlar) {  let yeniInt = parseSaatAraligi(yeniAralik);  for (let k of mevcutKayitlar) {    if (k.tarih === yeniTarih && String(k.personelId) === String(personelId)) {      let varolanInt = parseSaatAraligi(k.saatAraligi);      if (yeniInt.startMin < varolanInt.endMin && varolanInt.startMin < yeniInt.endMin) {        return true;      }    }  }  return false;}function nobetleriSirala(kayitlar) {  return [...kayitlar].sort((a, b) => {    if (a.tarih !== b.tarih) return a.tarih.localeCompare(b.tarih);    let idA = Number(a.personelId) || 0;    let idB = Number(b.personelId) || 0;    if (idA !== idB) return idA - idB;    let intA = parseSaatAraligi(a.saatAraligi);    let intB = parseSaatAraligi(b.saatAraligi);    return intA.startMin - intB.startMin;  });}function formatSaatGoster(toplamSaat) {  let saat = Math.floor(toplamSaat);  let dakika = Math.round((toplamSaat - saat) * 60);  if (dakika === 60) { saat += 1; dakika = 0; }  if (saat > 0 && dakika > 0) return `${saat} saat ${dakika} dk`;  if (saat > 0) return `${saat} saat`;  return `${dakika} dk`;}function nobetPaneliAc() {  const modal = document.createElement('div');  modal.style.cssText = `    position: fixed; top: 0; left: 0; width: 100%; height: 100%;    background: rgba(0,0,0,0.5); display: flex; align-items: center;    justify-content: center; z-index: 9999;  `;  modal.innerHTML = `    <div style="background:white; width:95%; max-width:450px; max-height:85vh; overflow-y:auto; padding:20px; border-radius:14px; box-shadow:0 4px 20px rgba(0,0,0,0.25);">      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:15px; border-bottom:1px solid #eee; padding-bottom:10px;">        <h3 style="margin:0; color:#e91e63; font-size:16px;">🌙 Nöbet Yönetim Paneli</h3>        <button onclick="this.parentElement.parentElement.parentElement.remove()" style="background:none; border:none; font-size:20px; cursor:pointer;">✕</button>      </div>      <div style="display:flex; flex-direction:column; gap:10px; margin-bottom:15px;">        <button onclick="nobetEkleModalAc()" style="background:#00897b; color:white; border:none; padding:10px; border-radius:8px; font-weight:bold; cursor:pointer; font-size:13px;">➕ Saat Aralıklı Nöbet Ekle</button>        <button onclick="nobetIstatistikGoster()" style="background:#1e88e5; color:white; border:none; padding:10px; border-radius:8px; font-weight:bold; cursor:pointer; font-size:13px;">📊 Nöbet Süre İstatistikleri</button>        <button onclick="nobetExcelAktar()" style="background:#43a047; color:white; border:none; padding:10px; border-radius:8px; font-weight:bold; cursor:pointer; font-size:13px;">📥 Düzenli Çizelgeyi Excel'e Aktar</button>      </div>      <div style="font-weight:bold; font-size:13px; color:#444; margin-bottom:5px;">Nöbet Çizelgesi:</div>      <div id="nobetListeContainer" style="border:1px solid #eee; background:#fafafa; padding:8px; border-radius:8px; max-height:200px; overflow-y:auto; font-size:12px;"></div>      <button onclick="this.parentElement.parentElement.remove()" style="background:#333; color:white; border:none; padding:10px; border-radius:8px; font-weight:bold; cursor:pointer; width:100%; margin-top:15px;">Kapat</button>    </div>  `;  document.body.appendChild(modal);  nobetGecmisiListele();}function nobetEkleModalAc() {  if (personeller.length === 0) {    return özelBildirimGoster("Önce ana listeye personel eklemelisiniz!");  }  let personelSecenekleri = personeller.map(p => `<option value="${p.id}">${p.adSoyad} (Sicil: ${p.id})</option>`).join('');  const modal = document.createElement('div');  modal.style.cssText = `    position: fixed; top: 0; left: 0; width: 100%; height: 100%;    background: rgba(0,0,0,0.6); display: flex; align-items: center;    justify-content: center; z-index: 10000;  `;  let bugunTarih = new Date().toISOString().split('T')[0];  modal.innerHTML = `    <div style="background:white; width:90%; max-width:360px; padding:20px; border-radius:14px; box-shadow:0 4px 20px rgba(0,0,0,0.25);">      <h3 style="margin-top:0; color:#00897b; font-size:15px;">➕ Saat Aralıklı Nöbet Atama</h3>      <div style="margin-bottom:10px;">        <label style="font-size:12px; font-weight:bold; color:#555;">Nöbet Tarihi:</label>        <input type="date" id="nobetTarihInput" value="${bugunTarih}" style="width:100%; padding:8px; border:1px solid #ccc; border-radius:6px; margin-top:4px; box-sizing:border-box;">      </div>      <div style="margin-bottom:10px; display:flex; gap:8px;">        <div style="flex:1;">          <label style="font-size:12px; font-weight:bold; color:#555;">Başlangıç Saati:</label>          <input type="text" id="nobetBaslangicSaat" value="08.00" style="width:100%; padding:8px; border:1px solid #ccc; border-radius:6px; margin-top:4px; box-sizing:border-box;">        </div>        <div style="flex:1;">          <label style="font-size:12px; font-weight:bold; color:#555;">Bitiş Saati:</label>          <input type="text" id="nobetBitisSaat" value="10.00" style="width:100%; padding:8px; border:1px solid #ccc; border-radius:6px; margin-top:4px; box-sizing:border-box;">        </div>      </div>      <div style="margin-bottom:10px;">        <label style="font-size:12px; font-weight:bold; color:#555;">Nöbet Türü / Görev Yeri:</label>        <input type="text" id="nobetTurInput" placeholder="Örn: Nizamiyet / Devriye" style="width:100%; padding:8px; border:1px solid #ccc; border-radius:6px; margin-top:4px; box-sizing:border-box;">      </div>      <div style="margin-bottom:15px;">        <label style="font-size:12px; font-weight:bold; color:#555;">Personel Seç:</label>        <select id="nobetPersonelSecici" style="width:100%; padding:8px; border:1px solid #ccc; border-radius:6px; margin-top:4px; box-sizing:border-box;">          ${personelSecenekleri}        </select>      </div>      <div style="display:flex; justify-content:flex-end; gap:8px;">        <button onclick="this.parentElement.parentElement.parentElement.remove()" style="background:#999; color:white; border:none; padding:8px 12px; border-radius:6px; font-weight:bold; cursor:pointer;">İptal</button>        <button id="nobetKaydetOnayBtn" style="background:#00897b; color:white; border:none; padding:8px 12px; border-radius:6px; font-weight:bold; cursor:pointer;">Kaydet</button>      </div>    </div>  `;  document.body.appendChild(modal);  modal.querySelector('#nobetKaydetOnayBtn').onclick = () => {    let tarih = document.getElementById('nobetTarihInput').value;    let basSaat = document.getElementById('nobetBaslangicSaat').value.trim();    let bitSaat = document.getElementById('nobetBitisSaat').value.trim();    let tur = document.getElementById('nobetTurInput').value.trim();    let personelId = document.getElementById('nobetPersonelSecici').value;    if (!tur || !basSaat || !bitSaat) {      return özelBildirimGoster("Lütfen saatleri ve nöbet türünü eksiksiz doldurun!");    }    let p = personeller.find(x => String(x.id) === String(personelId));    if (!p) return;    let saatAraligi = `${basSaat} - ${bitSaat}`;    let kayitlar = nobetVerileriniGetir();    if (saatlerCisiyorMu(tarih, saatAraligi, p.id, kayitlar)) {      return alert(`⚠️ Çakışma Uyarısı: "${p.adSoyad}" adlı personelin ${tarih} tarihinde bu saat aralığıyla kesişen başka bir nöbeti bulunuyor!`);    }    kayitlar.push({      id: Date.now(),      tarih: tarih,      saatAraligi: saatAraligi,      tur: tur,      personelId: p.id,      adSoyad: p.adSoyad    });    nobetVerileriniKaydet(kayitlar);    modal.remove();    özelBildirimGoster("Saat aralıklı nöbet başarıyla eklendi.");    nobetGecmisiListele();  };}function nobetGecmisiListele() {  let container = document.getElementById('nobetListeContainer');  if (!container) return;  let kayitlar = nobetVerileriniGetir();  if (kayitlar.length === 0) {    container.innerHTML = `<div style="text-align:center; color:#888; padding:10px;">Henüz kayıtlı nöbet yok.</div>`;    return;  }  let siraliKayitlar = nobetleriSirala(kayitlar);  let html = '';  siraliKayitlar.forEach((k) => {    html += `      <div style="display:flex; justify-content:space-between; align-items:center; padding:6px; border-bottom:1px solid #eee; background:white; border-radius:4px; margin-bottom:4px;">        <div>          <b style="color:#333;">📅 ${k.tarih} | [Sicil: ${k.personelId}] ${k.adSoyad}</b> <span style="color:#666;">(${k.tur})</span>          <div style="font-size:10px; color:#888;">⏰ <b>${k.saatAraligi || 'Tüm Gün'}</b></div>        </div>        <button onclick="nobetKayitSil(${k.id})" style="background:#e53935; color:white; border:none; padding:3px 6px; border-radius:4px; font-size:10px; cursor:pointer;">Sil</button>      </div>    `;  });  container.innerHTML = html;}function nobetKayitSil(id) {  if (confirm("Bu nöbet kaydını silmek istediğinize emin misiniz?")) {    let kayitlar = nobetVerileriniGetir();    kayitlar = kayitlar.filter(k => k.id !== id);    nobetVerileriniKaydet(kayitlar);    nobetGecmisiListele();  }}function nobetIstatistikGoster() {  let kayitlar = nobetVerileriniGetir();  if (kayitlar.length === 0) {    return özelBildirimGoster("İstatistik oluşturulacak nöbet kaydı bulunmuyor.");  }  const modal = document.createElement('div');  modal.style.cssText = `    position: fixed; top: 0; left: 0; width: 100%; height: 100%;    background: rgba(0,0,0,0.6); display: flex; align-items: center;    justify-content: center; z-index: 10000;  `;  let bugunYilAy = new Date().toISOString().slice(0, 7);  let bugunTarih = new Date().toISOString().split('T')[0];  modal.innerHTML = `    <div style="background:white; width:92%; max-width:440px; max-height:85vh; overflow-y:auto; padding:20px; border-radius:14px; box-shadow:0 4px 20px rgba(0,0,0,0.25);">      <h3 style="margin-top:0; color:#1e88e5; font-size:16px;">📊 Personel Nöbet Süre İstatistikleri</h3>      <div style="display:flex; gap:8px; margin-bottom:10px;">        <div style="flex:1;">          <label style="font-size:11px; font-weight:bold; color:#555;">Filtre Türü:</label>          <select id="istatistikFiltreTuru" style="width:100%; padding:6px; border:1px solid #ccc; border-radius:6px; margin-top:3px; font-size:12px;">            <option value="tum">Tüm Zamanlar</option>            <option value="aylik" selected>Aylık</option>            <option value="gunluk">Günlük</option>          </select>        </div>        <div style="flex:1;">          <label style="font-size:11px; font-weight:bold; color:#555;" id="istatistikLabel">Ay Seçin:</label>          <input type="month" id="istatistikAyInput" value="${bugunYilAy}" style="width:100%; padding:6px; border:1px solid #ccc; border-radius:6px; margin-top:3px; font-size:12px; box-sizing:border-box;">          <input type="date" id="istatistikGunInput" value="${bugunTarih}" style="width:100%; padding:6px; border:1px solid #ccc; border-radius:6px; margin-top:3px; font-size:12px; box-sizing:border-box; display:none;">        </div>      </div>      <div id="istatistikIcerikContainer" style="border:1px solid #eee; background:#fafafa; padding:8px; border-radius:8px; max-height:260px; overflow-y:auto;"></div>      <button onclick="this.parentElement.parentElement.remove()" style="background:#333; color:white; border:none; padding:10px; border-radius:8px; font-weight:bold; cursor:pointer; width:100%; margin-top:15px;">Kapat</button>    </div>  `;  document.body.appendChild(modal);  let turSelect = modal.querySelector('#istatistikFiltreTuru');  let ayInput = modal.querySelector('#istatistikAyInput');  let gunInput = modal.querySelector('#istatistikGunInput');  let label = modal.querySelector('#istatistikLabel');  function guncelleIstatistikListesi() {    let secim = turSelect.value;    let filtrelenmisKayitlar = [...kayitlar];    if (secim === 'aylik') {      let secilenAy = ayInput.value;      if (secilenAy) filtrelenmisKayitlar = kayitlar.filter(k => k.tarih && k.tarih.startsWith(secilenAy));    } else if (secim === 'gunluk') {      let secilenGun = gunInput.value;      if (secilenGun) filtrelenmisKayitlar = kayitlar.filter(k => k.tarih === secilenGun);    }    let container = modal.querySelector('#istatistikIcerikContainer');    if (filtrelenmisKayitlar.length === 0) {      container.innerHTML = `<div style="text-align:center; color:#888; padding:15px; font-size:12px;">Seçilen kriterlere uygun nöbet kaydı bulunamadı.</div>`;      return;    }    let istatistikMap = {};    filtrelenmisKayitlar.forEach(k => {      if (!istatistikMap[k.adSoyad]) istatistikMap[k.adSoyad] = { toplamSaat: 0, detaylar: {} };      let saatMiktari = saatAraliginiHesapla(k.saatAraligi);      istatistikMap[k.adSoyad].toplamSaat += saatMiktari;      if (!istatistikMap[k.adSoyad].detaylar[k.tur]) istatistikMap[k.adSoyad].detaylar[k.tur] = 0;      istatistikMap[k.adSoyad].detaylar[k.tur] += saatMiktari;    });    let listeHtml = '';    Object.keys(istatistikMap).forEach(isim => {      let veri = istatistikMap[isim];      let genelSureStr = formatSaatGoster(veri.toplamSaat);      let detayStr = Object.keys(veri.detaylar).map(tur => `${tur}: ${formatSaatGoster(veri.detaylar[tur])}`).join(' | ');      listeHtml += `        <div style="padding:8px; border-bottom:1px solid #eee; background:white; border-radius:6px; margin-bottom:6px;">          <div style="display:flex; justify-content:space-between; font-weight:bold; color:#1e88e5; font-size:12px;">            <span>👤 ${isim}</span>            <span style="background:#e3f2fd; color:#1e88e5; padding:2px 6px; border-radius:4px; font-size:11px;">Toplam: ${genelSureStr}</span>          </div>          <div style="font-size:11px; color:#666; margin-top:3px;">${detayStr}</div>        </div>      `;    });    container.innerHTML = listeHtml;  }  turSelect.onchange = () => {    if (turSelect.value === 'tum') {      ayInput.style.display = 'none';      gunInput.style.display = 'none';      label.style.display = 'none';    } else if (turSelect.value === 'aylik') {      ayInput.style.display = 'block';      gunInput.style.display = 'none';      label.style.display = 'block';      label.innerText = 'Ay Seçin:';    } else if (turSelect.value === 'gunluk') {      ayInput.style.display = 'none';      gunInput.style.display = 'block';      label.style.display = 'block';      label.innerText = 'Gün Seçin:';    }    guncelleIstatistikListesi();  };  ayInput.onchange = guncelleIstatistikListesi;  gunInput.onchange = guncelleIstatistikListesi;  guncelleIstatistikListesi();}function ozelPromptGoster(baslik, mevcutDeger, callback) {  const modal = document.getElementById('customPromptModal');  const title = document.getElementById('customPromptTitle');  const input = document.getElementById('customPromptInput');  const btnOk = document.getElementById('customPromptOk');  const btnCancel = document.getElementById('customPromptCancel');  if (title) title.innerText = baslik;  if (input) input.value = mevcutDeger || '';  if (modal) modal.style.display = 'flex';  setTimeout(() => {    if (input) {        input.focus();        input.scrollIntoView({ behavior: 'smooth', block: 'center' });    }  }, 100);  if (btnOk && btnCancel) {      const yeniBtnOk = btnOk.cloneNode(true);      const yeniBtnCancel = btnCancel.cloneNode(true);      btnOk.parentNode.replaceChild(yeniBtnOk, btnOk);      btnCancel.parentNode.replaceChild(yeniBtnCancel, btnCancel);      document.getElementById('customPromptOk').addEventListener('click', () => {        const deger = document.getElementById('customPromptInput').value;        if (modal) modal.style.display = 'none';        if (callback) callback(deger);      });      document.getElementById('customPromptCancel').addEventListener('click', () => {        if (modal) modal.style.display = 'none';        if (callback) callback(null);      });  }}function nobetExcelAktar() {  if (typeof XLSX === 'undefined') {    return özelBildirimGoster("Excel kütüphanesi (SheetJS) yüklenemedi.");  }  let kayitlar = nobetVerileriniGetir();  if (kayitlar.length === 0) {    return özelBildirimGoster("Dışa aktarılacak nöbet kaydı bulunmuyor.");  }  let siraliKayitlar = nobetleriSirala(kayitlar);  let excelMatris = [    ["Nöbet Tarihi", "Personel Sicil No", "Personel Adı Soyadı", "Saat Aralığı", "Süre (Saat)", "Nöbet Türü / Görev"]  ];  siraliKayitlar.forEach(k => {    let saatMiktari = saatAraliginiHesapla(k.saatAraligi);    excelMatris.push([k.tarih, k.personelId, k.adSoyad, k.saatAraligi || '-', saatMiktari.toFixed(2), k.tur]);  });  let ws = XLSX.utils.aoa_to_sheet(excelMatris);  let colWidths = [];  excelMatris.forEach(row => {    row.forEach((cell, colIndex) => {      let cellLength = cell ? String(cell).length : 0;      if (!colWidths[colIndex] || cellLength > colWidths[colIndex]) {        colWidths[colIndex] = cellLength;      }    });  });  ws['!cols'] = colWidths.map(w => ({ wch: Math.max(w + 4, 12) }));  let wb = XLSX.utils.book_new();  XLSX.utils.book_append_sheet(wb, ws, "Tarih ve Sicil Sıralı Çizelge");  try {    const excelBuffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });    const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });    const url = URL.createObjectURL(blob);    let a = document.createElement('a');    a.href = url;    a.download = 'Tarih_ve_Sicil_Sirali_Nobet_Cizelgesi.xlsx';    document.body.appendChild(a);    a.click();    setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 1000);    özelBildirimGoster("Nöbet çizelgesi Excel dosyası olarak indirildi.");  } catch (e) {    özelBildirimGoster("Excel oluşturulurken hata: " + e.message);  }}function tumVerileriSifirla() {  if (confirm("Tüm verileriniz, şablonlarınız ve ayarlarınız kalıcı olarak silinecek. Bu işlemi onaylıyor musunuz?")) {    localStorage.clear();        if (typeof özelBildirimGoster === 'function') {      özelBildirimGoster("Tüm veriler ve ayarlar sıfırlandı, sayfa yenileniyor...");    }    // İşlem bittikten yarım saniye sonra sayfayı yenile    setTimeout(() => {      location.reload();    }, 500);  }}